        {
          "term": "FOIL Record",
          "definition": "Any information kept, held, filed, produced, or reproduced by, with, or for an agency in any physical or electronic form."
        },
        {
          "term": "Constructive Denial",
          "definition": "An agency's failure to adhere to statutory FOIL deadlines (5-day acknowledgment or 20-day determination), giving the requester the immediate right to file an administrative appeal."
        },
        {
          "term": "Committee on Open Government (COOG)",
          "definition": "A state advisory body within the NYS Department of State that issues formal advisory opinions interpreting FOIL and the Open Meetings Law."
        }
